// Rule descriptor catalogue that defines the public rule metadata emitted by list-rules and reports.
import type { RuleDescriptor } from "./types.ts";

const RULE_DESCRIPTORS: readonly RuleDescriptor[] = [
  { ruleId: "complexity.cognitive", pillar: "complexity", severity: "warning", confidence: "high", description: "Flags syntax-aware decisions plus nested if, loop, switch, catch, and ternary depth; object and callback braces add no nesting.", remediation: "Split nested decisions into smaller named functions. Or raise rules.complexity.cognitive.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 15 },
  { ruleId: "complexity.cyclomatic", pillar: "complexity", severity: "warning", confidence: "high", description: "Counts a base path plus if, loop, catch, non-default case, ternary, &&, and || nodes; switch, default, ??, optional chains, and non-null assertions add zero.", remediation: "Reduce branching or move policy tables out of imperative code. Or raise rules.complexity.cyclomatic.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 15 },  { ruleId: "dead-code.unused-private-method", pillar: "dead-code", severity: "advisory", confidence: "low", description: "Flags private methods without an apparent same-file call site.", remediation: "Remove the method or add a direct call site.", falsePositiveShapes: [{ shape: "A private method reached only through non-literal dispatch - bracket access such as `this[\"handleRetry\"]()`, a string-keyed handler table, or a decorator/framework lifecycle hook - because the string form is blanked by the comment/string mask before counting, so neither the `name(` counter nor the `this.name` counter ever sees it.", mitigation: "Add a direct `this.handleRetry(...)` call site (or a typed dispatch map holding `this.handleRetry` rather than the string name), or set `rules.dead-code.unused-private-method.enabled: false`." }, { shape: "A private method exercised only from a sibling test file through an `(instance as any).method()` cast, since `analyseDeadCode` is invoked per file from the analyser and has no cross-file view of usage.", mitigation: "Drop `private` if the method is genuinely part of the surface under test, or set `rules.dead-code.unused-private-method.enabled: false`." }] },
  { ruleId: "design.circular-import", pillar: "design", severity: "warning", confidence: "medium", description: "Flags strongly connected relative import components that include the scan surface.", remediation: "Extract the shared contract or invert one dependency.", falsePositiveShapes: [{ shape: "A cycle completed only by an inline type-only specifier such as `import { type Config } from \"./b.ts\"`: `isTypeOnlyImportStatement` matches only the statement-level `import type` / `export type` form, so the inline `{ type ... }` form is recorded as a runtime edge and joins the SCC even though it is erased at compile time.", mitigation: "Rewrite the specifier as a statement-level `import type { Config } from \"./b.ts\"`, which `circularImportTargets` then excludes from the graph; failing that, set `rules.design.circular-import.enabled: false`." }, { shape: "A barrel/index re-export facade: `resolveRelativeImport` tries barrel candidates, so a module importing from its own directory's `index.ts` while that barrel re-exports the module forms an SCC that bundlers and Node resolve without incident.", mitigation: "Import the concrete module path instead of the barrel from inside the barrel's own directory, or set `rules.design.circular-import.enabled: false`." }] },
  { ruleId: "design.deep-relative-import", pillar: "design", severity: "advisory", confidence: "medium", description: "Flags relative imports that climb too many parent directories.", remediation: "Move the shared module closer or add a local boundary. Or raise rules.design.deep-relative-import.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 2, falsePositiveShapes: [{ shape: "An import that intentionally leaves the scanned surface - a monorepo sibling package or a repo-root shared config reached as `../../../shared/config.ts` - is still flagged, because `importEdgeForSpecifier` sets `parentSegments` from the raw specifier and emits the edge even when `resolveRelativeImport` finds no in-project `targetPath` to move closer.", mitigation: "Replace the climb with a package name or a tsconfig path alias (non-relative specifiers are dropped by the detector), or raise `rules.design.deep-relative-import.threshold` in .gruff-ts.yaml." }, { shape: "A deliberately deep test or fixture tree whose files reach a shared helper, e.g. `tests/unit/rules/design/x.test.ts` importing `../../../../src/thing.ts`, which is the normal layout cost rather than a design defect.", mitigation: "Raise `rules.design.deep-relative-import.threshold` to match the repository's test depth, or set `rules.design.deep-relative-import.enabled: false`." }] },
  { ruleId: "design.large-module-concentration", pillar: "design", severity: "advisory", confidence: "medium", description: "Flags a production module that dominates project source lines.", remediation: "Split unrelated responsibilities once stable seams are visible. Or raise rules.design.large-module-concentration.threshold or tune minFiles, minLines under rules.design.large-module-concentration.options.", threshold: 55, optionKeys: ["minFiles", "minLines"], falsePositiveShapes: [{ shape: "A single-purpose data module - a generated catalogue, a lookup table, or one long constant literal - legitimately holds most production lines while containing no mixed responsibilities to split.", mitigation: "Raise `rules.design.large-module-concentration.threshold` above the observed share, or raise `rules.design.large-module-concentration.options.minLines` so data modules of that size stop qualifying." }, { shape: "A project just over the file-count floor (four production sources by default) where one entrypoint naturally dominates simply because there are so few peers to dilute the share.", mitigation: "Raise `rules.design.large-module-concentration.options.minFiles` so the rule waits until the project is large enough for the share to mean something." }] },
  { ruleId: "design.package-bin-missing", pillar: "design", severity: "warning", confidence: "high", description: "Flags package bin entries that point at missing files.", remediation: "Update the bin path or add the executable file." },
  { ruleId: "design.package-bin-not-executable", pillar: "design", severity: "warning", confidence: "high", description: "Flags package bin targets that are not executable.", remediation: "Make the bin target executable and keep its shebang valid." },
  { ruleId: "docs.fixture-purpose-missing", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags large or scanner-relevant fixtures without a nearby purpose comment.", remediation: "Add a comment on or directly above the fixture (or above the test declaration) explaining what scanner path, regression, or fixture behavior it covers.", falsePositiveShapes: [{ shape: "A long inline fixture whose intent is already stated in the enclosing test(\"...\") title rather than in a comment, so hasFixturePurposeComment finds nothing at either accepted position.", mitigation: "Move one sentence of that intent into a comment directly above the test declaration (or on the fixture), or set rules.docs.fixture-purpose-missing.enabled to false." }, { shape: "A 12+ line template literal in a test file that is expected/golden output rather than an input fixture, where a rationale comment adds nothing.", mitigation: "Add a short comment naming the scanner path it pins, or set rules.docs.fixture-purpose-missing.enabled to false." }] },
  { ruleId: "docs.magic-threshold-without-rationale", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags threshold-like numeric values without a nearby rationale comment.", remediation: "Explain the threshold, limit, budget, or default near the value.", falsePositiveShapes: [{ shape: "A self-evident value whose identifier merely happens to contain a matched word, such as const maxIndex = items.length - 1 or const defaultLabel = \"\", which has no tuning decision to justify.", mitigation: "Put a short comment on the line above containing one of because/limit/default, or set rules.docs.magic-threshold-without-rationale.enabled to false." }, { shape: "A threshold whose rationale is documented centrally (config schema, docs/rules.md, an ADR) rather than adjacent to the declaration, which hasNearbyThresholdRationale cannot see.", mitigation: "Restate one clause of the rationale in a comment immediately above the value, or set rules.docs.magic-threshold-without-rationale.enabled to false." }] },
  { ruleId: "docs.missing-error-behavior-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags commented functions whose error behavior is not described.", remediation: "Document thrown errors, diagnostics, exits, reports, or recovery behavior.", falsePositiveShapes: [{ shape: "A function whose only error signal is findings.push( or diagnostics.push( — every rule detector in an analyser-shaped codebase appends findings without throwing, recovering, or exiting.", mitigation: "Use the word \"reports\" in the function's comment, or set rules.docs.missing-error-behavior-doc.enabled to false." }, { shape: "A try/catch used purely as an existence probe (JSON.parse guarded to return a default) where the comment already says \"defaults to X\" but never uses the words fallback or recover.", mitigation: "Reword the comment to include fallback or recover, which hasErrorBehaviorMarker accepts." }] },
  { ruleId: "docs.missing-exported-function-doc", pillar: "documentation", severity: "warning", confidence: "medium", description: "Flags exported functions without a leading maintainer comment.", remediation: "Add a JSDoc or line comment explaining the exported API's contract, since public surface has a higher cost of omission.", falsePositiveShapes: [{ shape: "A trivially self-evident exported wrapper or re-export shim (export function toJson(x: X): string { return JSON.stringify(x); }) where any honest comment restates the name — and then trips docs.useless-docblock instead.", mitigation: "Write a line comment that states the contract rather than the name (hasUsefulCommentContext vocabulary keeps useless-docblock quiet), or set rules.docs.missing-exported-function-doc.enabled to false." }] },
  { ruleId: "docs.missing-file-overview", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags source files without a top-of-file purpose comment.", remediation: "Add a brief file overview before imports or declarations.", falsePositiveShapes: [{ shape: "A file that opens with a directive prologue such as \"use client\"; or \"use strict\"; — only #! is skipped by hasFileOverviewComment, so the overview comment on the next line is never seen.", mitigation: "Move the overview comment above the directive, or set rules.docs.missing-file-overview.enabled to false." }, { shape: "A barrel or index file that only re-exports and genuinely has no purpose beyond its name, where the module's purpose is documented above its main export lower in the file.", mitigation: "Add a one-line comment above the first import, or set rules.docs.missing-file-overview.enabled to false." }] },
  { ruleId: "docs.missing-internal-function-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags internal helper functions without a leading maintainer comment.", remediation: "Add a short comment explaining the helper's role; internal helpers are advisory, exported surface fires the warning variant.", falsePositiveShapes: [{ shape: "Small single-expression private helpers extracted purely to name a sub-step, where the name already is the documentation and every added comment restates it.", mitigation: "Set rules.docs.missing-internal-function-doc.enabled to false if the project documents only its exported surface; otherwise add a comment stating the helper's role rather than its name." }] },
  { ruleId: "docs.missing-interface-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags interfaces without a leading maintainer comment.", remediation: "Add a short JSDoc or line comment explaining the interface contract.", falsePositiveShapes: [{ shape: "A small file-local interface that exists only as one function's argument bundle or an internal row shape, which interfaceDeclarations still matches because the export keyword is optional in its regex.", mitigation: "Add a one-line // comment above it (a line comment satisfies hasLeadingCommentBeforeLine), or set rules.docs.missing-interface-doc.enabled to false." }, { shape: "Interfaces in ambient or generated declaration surfaces where each member is already self-describing and per-interface prose is churn.", mitigation: "Exclude the generated path from the scan, or set rules.docs.missing-interface-doc.enabled to false." }] },
  { ruleId: "docs.missing-invariant-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags commented declarations that own schema, fingerprint, baseline, or determinism contracts without saying so.", remediation: "Document the invariant, contract, schema, fingerprint, or deterministic behavior.", falsePositiveShapes: [{ shape: "Any helper that calls .sort( for purely local ordering — the signal regex matches the bare word sort, so a one-line comparator wrapper with no ordering contract to publish is flagged.", mitigation: "Say \"stable\" or \"deterministic\" in the comment if the ordering does matter, otherwise set rules.docs.missing-invariant-doc.enabled to false." }, { shape: "Any function that merely mentions the type name Finding (pervasive in analyser-shaped code) or a local variable named baseline, which trips the contract vocabulary without owning a contract.", mitigation: "Add one of invariant/contract/schema/fingerprint to the comment where a contract really exists, or set rules.docs.missing-invariant-doc.enabled to false." }] },
  { ruleId: "docs.missing-param-tag", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags documented exports with parameters missing @param tags.", remediation: "Document every current parameter in the JSDoc.", falsePositiveShapes: [{ shape: "A docblock deliberately written as a one-paragraph prose summary with no tags at all — the rule then fires once per parameter, turning one stylistic choice into N findings.", mitigation: "Either add an @param line per parameter or set rules.docs.missing-param-tag.enabled to false for projects that document behaviour in prose." }, { shape: "Destructured or options-object parameters, where the docblock documents the individual option keys rather than the binding pattern the parser reports as the parameter name.", mitigation: "Add a single @param tag named after the whole options parameter alongside the per-key lines, or set rules.docs.missing-param-tag.enabled to false." }] },
  { ruleId: "docs.missing-public-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags exported class, type, and enum APIs without a nearby doc comment.", remediation: "Add a short comment explaining the public API contract.", falsePositiveShapes: [{ shape: "An exported class, type, or enum documented with an ordinary // line comment — hasDocCommentBeforeLine accepts only /** openers and * continuation lines, so a perfectly good line comment does not count (unlike docs.missing-interface-doc, which accepts either).", mitigation: "Convert the comment to a /** ... */ block, or set rules.docs.missing-public-doc.enabled to false." }, { shape: "Self-evident exported type aliases produced by the exportedDeclarations regex, such as export type Foo = Bar re-export shims that restate an already-documented type.", mitigation: "Add a one-line /** ... */ naming the reason for the alias, or set rules.docs.missing-public-doc.enabled to false." }] },
  { ruleId: "docs.missing-return-tag", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags documented non-void exports without @returns.", remediation: "Document the returned value or remove stale JSDoc.", falsePositiveShapes: [{ shape: "An async function annotated Promise<void> — the exemption regex is /^void\\b/, which does not match Promise<void>, so a function that returns nothing is still asked to document a return value.", mitigation: "Add an @returns line, or set rules.docs.missing-return-tag.enabled to false until the void check covers Promise<void>." }, { shape: "A docblock whose prose already explains the return value in a sentence rather than a tag — needsReturnTag tests only for the literal @return/@returns marker.", mitigation: "Convert that sentence into an @returns tag, or set rules.docs.missing-return-tag.enabled to false." }] },
  { ruleId: "docs.missing-side-effect-doc", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags commented functions that perform observable side effects without naming them.", remediation: "Name the filesystem, process, environment, network, or persistence side effect.", falsePositiveShapes: [{ shape: "A pure function whose name merely starts with write — the name arm of hasSideEffectSignal is /^(?:write|recordHistory|startDashboard)\\b/, so a string builder such as writeRow that touches nothing external is flagged.", mitigation: "Rename to a non-write verb (formatRow, renderRow), or set rules.docs.missing-side-effect-doc.enabled to false." }, { shape: "A function that genuinely has the side effect and documents it using different words (\"emits\", \"saves\", \"outputs\"), none of which appear in hasSideEffectMarker's nine-word vocabulary.", mitigation: "Reword the comment to use one of writes/reads/persists/mutates/starts/spawns/network/filesystem/environment." }] },
  { ruleId: "docs.missing-why-for-complex-code", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags comments on complex functions that do not explain why the shape exists.", remediation: "Explain the tradeoff, compatibility reason, or invariant behind the complex control flow.", falsePositiveShapes: [{ shape: "A long but flat dispatch — a big switch or a table-driven mapper — that crosses the cyclomatic gate purely by branch count while having no design tradeoff to explain.", mitigation: "Raise rules.complexity.cyclomatic.threshold (this rule reuses that key), or set rules.docs.missing-why-for-complex-code.enabled to false." }, { shape: "A comment that does explain the why using words outside the vocabulary list (\"historical\", \"workaround\", \"the spec requires\"), which hasComplexWhyMarker does not recognise.", mitigation: "Include one of because/why/intentional/tradeoff/compat/avoid/preserve, or phrases like \"due to\" or \"required by\", in the comment." }] },
  { ruleId: "docs.stale-comment", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags comments that reference missing files, unknown rules, stale CLI flags, or the wrong declaration.", remediation: "Update the comment or add historical context explaining why it remains useful.", falsePositiveShapes: [{ shape: "A path reference that exists but is unreachable from the two roots referencedPathExists tries — process cwd and the containing file's directory — such as a tsconfig path alias or a monorepo root above cwd.", mitigation: "Write the reference relative to the file or the project root, or set rules.docs.stale-comment.enabled to false." }, { shape: "A comment that deliberately names a symbol it delegates to (\"Wrapper around function `parseConfig`\") above a differently named declaration, which referencedDeclarationName reads as documenting the wrong declaration.", mitigation: "Drop the kind keyword before the backticked name, or include one of previously/legacy/compat/migration/ADR so isHistoricalContextComment exempts the comment." }] },
  { ruleId: "docs.stale-param-tag", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags @param tags for parameters no longer in the signature.", remediation: "Remove stale tags or update the function signature.", falsePositiveShapes: [{ shape: "An outer function whose docblock documents the parameters of the inner function it returns (curried factories, higher-order builders) — those tag names are absent from the outer signature.", mitigation: "Move those tags into the returned function's own docblock, or set rules.docs.stale-param-tag.enabled to false." }, { shape: "A docblock attached above an overload signature set where the tag names follow the implementation signature's names rather than the overload's.", mitigation: "Align the tag names with the signature the parser reports, or set rules.docs.stale-param-tag.enabled to false." }] },
  { ruleId: "docs.suppression-without-rationale", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags lint, formatter, coverage, or tool suppressions without a maintainer rationale.", remediation: "Explain why the suppression is intentional, a false positive, or tracked elsewhere.", falsePositiveShapes: [{ shape: "A suppression whose rationale is written in plain prose that misses the accepted vocabulary — \"upstream types are wrong here\" contains no because/intentional/false positive/tracked in/reason:/ticket/URL.", mitigation: "Prefix the explanation with \"reason:\" or start it with \"because\", both of which hasSuppressionRationale accepts." }, { shape: "A prettier-ignore above a hand-aligned table, matrix, or ASCII diagram, where the formatting intent is self-evident from the very lines below it.", mitigation: "Add \"because the alignment is load-bearing\" to the directive line, or set rules.docs.suppression-without-rationale.enabled to false." }] },
  { ruleId: "docs.todo-without-tracking", pillar: "documentation", severity: "advisory", confidence: "high", description: "Flags comments introduced by a TODO, FIXME, HACK, or XXX marker without tracking context; prose that only mentions a marker word stays quiet.", remediation: "Attach a tracking URL, issue id, owner, date, ADR, or .goat-flow task reference." },
  { ruleId: "docs.useless-docblock", pillar: "documentation", severity: "advisory", confidence: "medium", description: "Flags comments or docblocks that only restate the symbol name.", remediation: "Replace the comment with useful contract or behavior detail.", falsePositiveShapes: [{ shape: "A docblock made up entirely of @param/@returns tags with no prose — isUselessDocblock filters out every line starting with @ and then treats the empty remainder as useless, so a fully tagged, genuinely informative docblock is flagged.", mitigation: "Add one sentence of contract or behaviour prose above the tags, or set rules.docs.useless-docblock.enabled to false." }, { shape: "A short but real comment that happens to be the name plus one word (// Formats the report above formatReport), caught by the deliberate name-length-plus-one arm of isRestatingSignatureComment.", mitigation: "Extend the comment with contract detail, or use one of the hasUsefulCommentContext words (because, invariant, contract, throws, stable) which short-circuits the check." }] },
  { ruleId: "modernisation.date-now-candidate", pillar: "modernisation", severity: "advisory", confidence: "high", description: "Flags verbose current-time expressions that can use Date.now().", remediation: "Use Date.now() for current epoch milliseconds." },
  { ruleId: "modernisation.double-cast", pillar: "modernisation", severity: "warning", confidence: "medium", description: "Flags casts through unknown or any into another type.", remediation: "Use a parser, type guard, or narrower assertion.", falsePositiveShapes: [{ shape: "A deliberate, documented trust-boundary cast (parsing an external payload) still emits a finding; hasDoubleCastTrustBoundaryRationale only lowers severity to advisory when the same line carries a comment naming a trust boundary, validator, or TS2352.", mitigation: "Add an inline comment on the cast line naming the boundary (e.g. `// wire format, validated`) to keep it advisory, or set `rules.modernisation.double-cast.enabled` to false." }, { shape: "Test doubles that widen a partial literal into a full interface (`{} as unknown as Client`) fire exactly like production casts because there is no test-path gate.", mitigation: "Build the double through a typed factory or a `satisfies`-checked fixture, or disable `rules.modernisation.double-cast.enabled` for the run." }] },
  { ruleId: "modernisation.loose-equality", pillar: "modernisation", severity: "advisory", confidence: "medium", description: "Flags loose equality comparisons that may coerce values.", remediation: "Use === or !== unless intentionally checking nullish values.", falsePositiveShapes: [{ shape: "An intentional nullish double-test written as `x == undefined`: isNullEqualityComparison only whitelists a literal `null` operand (`/\\bnull$/` on the left, `/^null\\b/` on the right), so the `undefined` spelling of the same idiom is flagged.", mitigation: "Write the idiom as `x == null`, which the detector recognises and skips, or set `rules.modernisation.loose-equality.enabled` to false." }, { shape: "Only the first coercing comparison per line is reported, so a line mixing an intentional `== null` guard first with a real coercion later can surface a confusing single finding anchored at the line rather than the operator.", mitigation: "Split the compound condition onto separate lines so each comparison is judged on its own." }] },
  { ruleId: "modernisation.non-null-assertion", pillar: "modernisation", severity: "warning", confidence: "medium", description: "Flags non-null assertions that bypass null checks.", remediation: "Narrow the value or handle null and undefined explicitly.", falsePositiveShapes: [{ shape: "An assertion that is provably safe from a guard earlier in the same function (`if (!user) return; … user!.id`): the check is per-line regex matching with no flow analysis, so the preceding narrowing is invisible to it.", mitigation: "Bind the narrowed value to a local (`const found = user; …`) so the `!` disappears, or set `rules.modernisation.non-null-assertion.enabled` to false." }, { shape: "A single chained expression such as `a!.b!.c` emits one finding per `!`, so one design decision is counted several times in the report.", mitigation: "Narrow once into a local before the chain, which collapses the repeated assertions into a single guarded access." }] },
  { ruleId: "modernisation.nullish-coalescing-candidate", pillar: "modernisation", severity: "advisory", confidence: "medium", description: "Flags || fallbacks that may erase valid falsy values.", remediation: "Use ?? when only null or undefined should fall back.", falsePositiveShapes: [{ shape: "A deliberate falsy-coalescing default where empty string or 0 genuinely must fall back (`const label = name || \"unknown\"` for a user-supplied blank field); switching to `??` would change behaviour, so the flagged line is correct as written.", mitigation: "Keep `||` and set `rules.modernisation.nullish-coalescing-candidate.enabled` to false, or make the intent explicit with a comparison such as `name.trim() === \"\" ? \"unknown\" : name`." }] },
  { ruleId: "modernisation.object-spread-candidate", pillar: "modernisation", severity: "advisory", confidence: "medium", description: "Flags Object.assign({}, ...) cloning that can use object spread.", remediation: "Use object spread when shallow-cloning plain objects.", falsePositiveShapes: [{ shape: "Code compiled for an output target that predates object spread (ES2017 and earlier), where `Object.assign({}, …)` is the intentional emitted form and spread would be downlevelled or unsupported.", mitigation: "Set `rules.modernisation.object-spread-candidate.enabled` to false for projects pinned to a pre-ES2018 target." }, { shape: "A multi-source merge such as `Object.assign({}, defaults, overrides, extra)` is flagged with the same clone message even though the rewrite is a multi-spread expression rather than a simple clone.", mitigation: "Rewrite as `{ ...defaults, ...overrides, ...extra }` when that reads better, or disable the rule if the merge helper is intentional." }] },
  { ruleId: "modernisation.optional-chaining-candidate", pillar: "modernisation", severity: "advisory", confidence: "medium", description: "Flags repeated guard-and-property access patterns.", remediation: "Use optional chaining for clearer null-safe access.", falsePositiveShapes: [{ shape: "A guard where the left operand is deliberately tested for truthiness beyond nullishness — `count && count.toFixed(2)` must short-circuit on 0, and `text && text.trim()` on the empty string — so `?.` would change the expression's value.", mitigation: "Keep the `&&` guard when a falsy-but-present value must short-circuit, or set `rules.modernisation.optional-chaining-candidate.enabled` to false." }] },
  { ruleId: "modernisation.public-property", pillar: "modernisation", severity: "advisory", confidence: "high", description: "Flags public class properties that expose representation.", remediation: "Prefer readonly properties or accessors when invariants matter." },
  { ruleId: "modernisation.readonly-property-candidate", pillar: "modernisation", severity: "advisory", confidence: "medium", description: "Flags class properties that appear readonly-worthy.", remediation: "Mark the property readonly when mutation is not part of the contract.", falsePositiveShapes: [{ shape: "A genuinely mutable field reassigned after construction (a cursor, cache slot, or field cleared by a `reset()` method): the regex performs no assignment analysis, so any non-readonly annotated field matches.", mitigation: "Leave the field mutable and set `rules.modernisation.readonly-property-candidate.enabled` to false for classes that hold mutable state by design." }] },
  { ruleId: "modernisation.ts-comment-without-rationale", pillar: "modernisation", severity: "warning", confidence: "medium", description: "Flags TypeScript suppression comments without a rationale.", remediation: "Add a short reason or remove the suppression.", falsePositiveShapes: [{ shape: "A directive whose explanation is written on the line above rather than after the directive: hasDirectiveRationale only reads the text following `@ts-ignore` / `@ts-expect-error` on that same line.", mitigation: "Move the reason onto the directive line (`// @ts-expect-error upstream types lag the runtime`) so the same-line heuristic sees it." }, { shape: "A terse but adequate reason of one or two words (`// @ts-expect-error legacy shim`) fails the three-word bar in hasDirectiveRationale and is reported as unexplained.", mitigation: "Expand to three or more words, or include a tracking token such as an issue id or URL, both of which the heuristic accepts." }] },
  { ruleId: "modernisation.tsconfig-exact-optional-disabled", pillar: "modernisation", severity: "warning", confidence: "high", description: "Flags tsconfig files without exactOptionalPropertyTypes enabled.", remediation: "Enable exactOptionalPropertyTypes unless migration is blocked." },
  { ruleId: "modernisation.tsconfig-index-safety-disabled", pillar: "modernisation", severity: "warning", confidence: "high", description: "Flags tsconfig files without noUncheckedIndexedAccess enabled.", remediation: "Enable noUncheckedIndexedAccess unless migration is blocked." },
  { ruleId: "modernisation.tsconfig-strict-disabled", pillar: "modernisation", severity: "warning", confidence: "high", description: "Flags tsconfig files without strict mode enabled.", remediation: "Enable strict unless migration is blocked." },
  { ruleId: "modernisation.var-declaration", pillar: "modernisation", severity: "advisory", confidence: "high", description: "Flags var declarations.", remediation: "Use let or const with the narrowest useful scope." },
  { ruleId: "naming.acronym-case", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags a known acronym cased inconsistently across a file's chosen-case names; SCREAMING_SNAKE constants and all-lower names are convention-forced and exempt.", remediation: "Use one casing for each acronym throughout the file. Or extend allowlists.knownAcronyms with project-specific values.", allowlistKeys: ["knownAcronyms"], falsePositiveShapes: [{ shape: "JavaScript camelCase forces a leading acronym token to lowercase, so a file holding idiomatic `urlBuilder` or `idToken` (lower class) beside `parseURL` or `RequestID` (upper class) is reported as drift though both follow one convention.", mitigation: "Remove the affected acronym (e.g. `url`, `id`) from allowlists.knownAcronyms, or set rules.naming.acronym-case.enabled to false." }, { shape: "A module mirroring an external SDK's own casing - a vendor type such as `APIKeyOptions` next to the project's local `apiKey` field - is flagged although the upper-case spelling is fixed by the third-party contract.", mitigation: "Rename only the local identifier to match the vendor spelling, or drop that acronym from allowlists.knownAcronyms so the file-wide comparison stops for it." }] },
  { ruleId: "naming.boolean-prefix", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags boolean names without intent-revealing prefixes on declarations, function parameters (typed `: boolean` or with `= true|false` default), and interface/type-literal fields.", remediation: "Rename local booleans with an intent prefix. For contract fields, rename or map the key at serialization, or replace allowlists.acceptedBooleanNames with a complete list that includes it.", allowlistKeys: ["booleanPrefixes", "acceptedBooleanNames"], falsePositiveShapes: [{ shape: "Adjective or participle state booleans such as `enabled`, `ready`, `visible`, or `dirty` on a local declaration or parameter: the prefix regex requires an uppercase letter after the prefix, so a whole word can never satisfy it, and `function isAcceptedBooleanStateName` covers only seven exact names plus seven suffixes.", mitigation: "Rename with an intent prefix (`isEnabled`), or set rules.naming.boolean-prefix.enabled to false - allowlists.booleanPrefixes only accepts prefixes, not whole words." }, { shape: "An external contract key destructured or declared as a local const or parameter (`verbose`, `force`, `quiet` from a CLI options bag) still fires, because `function isAcceptedContractBooleanName` applies allowlists.acceptedBooleanNames only when surface is \"interface-field\".", mitigation: "Declare the flag as an interface/type-literal field and list it in allowlists.acceptedBooleanNames (that key replaces the built-in list, so restate every name you still want), or map the key at the serialization boundary." }] },
  { ruleId: "naming.class-file-mismatch", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags a sole public class whose name differs from the file name.", remediation: "Rename the class or file, or add the exact fileBase:ClassName pair to allowlists.acceptedClassFilePairs.", allowlistKeys: ["acceptedClassFilePairs"], falsePositiveShapes: [{ shape: "A conventional entry file - `export default class UserService {}` in `index.ts`, or a role-named `handler.ts` holding one domain class - is flagged, because only the literal name \"default\" is exempted, not a named default export in a convention-named file.", mitigation: "Add the exact lowercase pair (for example `index:UserService`) to allowlists.acceptedClassFilePairs." }, { shape: "When the shared parse is unavailable the detector falls back to the legacy directly-exported inventory, which can undercount a module's other public declarations and make a class look like the sole public export of a multi-export feature module.", mitigation: "Add the fileBase:ClassName pair to allowlists.acceptedClassFilePairs, or export the class from a file named after it so the normalised-name check passes." }] },
  { ruleId: "naming.generic-function", pillar: "naming", severity: "advisory", confidence: "high", description: "Flags generic function names that hide intent.", remediation: "Name the domain action instead of a generic operation. Or remove the name from allowlists.bannedGenericNames if your project does not consider it generic.", allowlistKeys: ["bannedGenericNames"] },
  { ruleId: "naming.generic-parameter", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags placeholder parameter names in multi-parameter, long, exported, or complex functions.", remediation: "Use a name that describes the parameter's role. Or tune minCyclomatic, minLineCount, minParameters under rules.naming.generic-parameter.options.", optionKeys: ["minCyclomatic", "minLineCount", "minParameters"], falsePositiveShapes: [{ shape: "A genuinely type-generic utility - a serializer, deep-clone, or middleware whose parameter really is any `value`/`data`/`item` - trips the rule, because the gate measures only the function's size and arity, never whether the parameter has a nameable domain role.", mitigation: "Raise rules.naming.generic-parameter.options.minParameters / minLineCount / minCyclomatic, or set rules.naming.generic-parameter.enabled to false for that codebase." }, { shape: "The three thresholds are OR-ed, so any single-parameter function of 30 lines or more fires on a lone `value` argument even when its arity and complexity are trivial.", mitigation: "Raise rules.naming.generic-parameter.options.minLineCount above the length of those functions, or remove the word from allowlists.placeholderNames." }] },
  { ruleId: "naming.hungarian-notation", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags identifiers named after storage type prefixes.", remediation: "Name the domain concept instead of the storage type. Or remove the prefix from allowlists.hungarianPrefixes if your project does not consider it Hungarian-style.", allowlistKeys: ["hungarianPrefixes"], falsePositiveShapes: [{ shape: "Count-style names built on the default `num` prefix - `const numItems`, `private numRetries`, `let numRows` - match prefix-plus-uppercase and are reported, although `num` there abbreviates \"number of\" rather than tagging a storage type.", mitigation: "Remove `num` from allowlists.hungarianPrefixes (the key replaces the built-in list, so restate the prefixes you still want), or rename to `itemCount`." }] },
  { ruleId: "naming.identifier-quality", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags placeholder or numbered identifiers on declarations, function parameters, and destructured locals.", remediation: "Use names that explain domain role or intent. Or remove the name from allowlists.placeholderNames if your project considers it valid.", allowlistKeys: ["placeholderNames"], falsePositiveShapes: [{ shape: "A thin generic wrapper where the placeholder word IS the correct name: `const data = await response.json()` in a fetch helper, or `item` as the element of a genuinely type-parameterised list utility.", mitigation: "Remove that word from allowlists.placeholderNames (the key replaces the built-in list of foo/bar/baz/tmp/temp/thing/stuff/data/value/item), or rename to the domain noun." }, { shape: "Numbered operands whose digit carries real meaning - `value1` and `value2` in a pair comparison, `item2` in a two-column mapping - are reported as \"numbered\" because the stem matches, independent of context.", mitigation: "Rename to role names (`left`/`right`), or set rules.naming.identifier-quality.enabled to false; NUMBERED_PLACEHOLDER_STEMS is a built-in constant and is not exposed as a config key." }] },
  { ruleId: "naming.inconsistent-casing", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags one canonical identifier appearing in different forms within the same module, function, interface, or named type-literal owner.", remediation: "Choose one form within the owner, or add an exact alias pair to allowlists.acceptedCasingPairs.", allowlistKeys: ["acceptedCasingPairs"], falsePositiveShapes: [{ shape: "A deliberate serialization boundary inside one scope, where the wire form and the domain form of the same field must coexist - `const note_id = row.note_id;` next to `const noteId = ...` in module scope.", mitigation: "Add the exact pair to allowlists.acceptedCasingPairs, e.g. \"note_id:noteId\"." }, { shape: "A types module holding two vendors' contract fields for one concept (`user_id` from one API, `userId` from another) is still reported, because `function sameCasingSurfaceEntries` drops interface fields only when a local (non-contract) surface exists in the same group.", mitigation: "Add the exact alias pair to allowlists.acceptedCasingPairs, or split the two vendors' contracts into separate interfaces so the owner boundary separates them." }] },
  { ruleId: "naming.negative-boolean", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags boolean identifiers framed as a negation on declarations, parameters, and interface fields.", remediation: "Invert the framing so callers do not read a double negation. Or extend allowlists.negativeBooleanAllowed with project-specific values.", allowlistKeys: ["negativeBooleanAllowed"], falsePositiveShapes: [{ shape: "CLI and API flags whose negative framing IS the external contract - `noCache` behind `--no-cache`, or `skipValidation` on a published options interface - are flagged even though inverting the name would break the documented flag.", mitigation: "Add the name to allowlists.negativeBooleanAllowed (the key replaces the built-in list, so restate the names you still want), or invert it internally and map it at the option-parsing boundary." }, { shape: "Booleans that mirror an externally defined negative state with no natural positive inversion, such as `notFound` tracking an HTTP 404 result, match the `not` + uppercase pattern.", mitigation: "Add the name to allowlists.negativeBooleanAllowed, or rename to the positive domain fact (`missing`, `absent`)." }] },
  { ruleId: "naming.short-variable", pillar: "naming", severity: "advisory", confidence: "medium", description: "Flags very short variable names outside common loop counters; covers declarations, function parameters, and destructured locals.", remediation: "Use a name that describes the domain role. Or extend allowlists.acceptedAbbreviations with project-specific values.", allowlistKeys: ["acceptedAbbreviations"], falsePositiveShapes: [{ shape: "Two-character domain abbreviations outside the default set - `el`, `fn`, `ok`, `ts`, `dx` - are flagged wherever they are declared or destructured, even when the surrounding code makes their meaning obvious.", mitigation: "Add them to allowlists.acceptedAbbreviations (the key replaces the built-in list of age/app/db/fs/id/io/key/log/max/min/now/raw/rx/tx/ui/url, so restate the defaults you still want)." }, { shape: "A for-of binding whose body exceeds the hard-coded ten-line span still fires, so `for (const f of files) { ... }` over a 12-line body is reported although the binding's lifetime is still just that loop.", mitigation: "Rename the binding to the element's domain noun, or add the letter to allowlists.acceptedAbbreviations; the ten-line span is a constant in `function pushShortVariableAt` and has no config key." }] },
  { ruleId: "security.async-foreach", pillar: "security", severity: "warning", confidence: "medium", description: "Flags async callbacks passed to forEach.", remediation: "Use for...of with await, Promise.all, or an explicit queue.", falsePositiveShapes: [{ shape: "A project-defined forEach-like method may await callbacks even though its call text matches the built-in array shape.", mitigation: "Use an explicit awaited loop or queue, or review the custom iterator contract before accepting the warning." }] },
  { ruleId: "security.disabled-tls-verification", pillar: "security", severity: "error", confidence: "high", description: "Flags code that disables TLS certificate verification.", remediation: "Remove the override and fix certificate trust at the source." },
  { ruleId: "security.document-write", pillar: "security", severity: "warning", confidence: "high", description: "Flags document.write usage.", remediation: "Use safe DOM APIs and encode untrusted content." },
  { ruleId: "security.dynamic-regexp", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external input used to construct regular expressions.", remediation: "Use a fixed pattern, escape user input, or enforce strict length and character limits.", falsePositiveShapes: [{ shape: "`new RegExp(process.env.SOME_PATTERN)` in build, config, or tooling code, where the environment variable is operator-supplied rather than attacker-supplied — `process.env.*` is unconditionally one of the four external-input tokens.", mitigation: "Move the pattern to a literal constant in source, or disable the rule with `rules.security.dynamic-regexp.enabled: false`." }, { shape: "`new RegExp(escapeRegExp(req.query.q))` — the source token still sits inside the same call segment, so the already-escaped input is reported by the same-line matcher, which has no notion of a sanitiser.", mitigation: "Bound the input with an explicit length and character check as the descriptor's remediation says, or set `rules.security.dynamic-regexp.enabled: false` if your codebase routes all patterns through a shared escaper." }] },
  { ruleId: "security.eval-call", pillar: "security", severity: "error", confidence: "high", description: "Flags eval() dynamic code execution.", remediation: "Replace eval with explicit parsing or a safe dispatch table." },
  { ruleId: "security.floating-promise", pillar: "security", severity: "warning", confidence: "medium", description: "Flags promise-like calls without await, return, or void.", remediation: "Await it, return it, or mark intentional fire-and-forget with void.", falsePositiveShapes: [{ shape: "A synchronous function whose name merely ends in `Async` or `Promise` (`registerAsyncHandler(fn);`, `resolvePromise(x);`) is flagged purely on the name suffix — isPromiseLikeCall is a naming heuristic with no type information.", mitigation: "Rename so the callee's last dotted segment does not end in `Async`/`Promise`, or set `rules.security.floating-promise.enabled: false`." }, { shape: "A promise that IS handled, but on a following physical line — `loadAsync(url)` with `.catch(handleError);` wrapped onto the next line — because floatingPromiseCall only ever inspects one trimmed line.", mitigation: "Keep the `.catch(` or `.then(` on the same line as the call, or prefix the statement with `void`, which isHandledPromiseStatement accepts." }] },
  { ruleId: "security.github-actions-broad-permissions", pillar: "security", severity: "warning", confidence: "medium", description: "Flags GitHub Actions workflows that grant broad write permissions.", remediation: "Reduce workflow permissions to read-only by default and grant write scopes only to trusted jobs.", falsePositiveShapes: [{ shape: "A job that legitimately needs the grant — a release job with `contents: write`, a container job with `packages: write` — is reported the same as a blanket grant, because the rule has no notion of an intended-write job and reports one finding per write scope.", mitigation: "Keep the grant on the narrowest job rather than at workflow level (the finding still fires, but the blast radius shrinks), or set `rules.security.github-actions-broad-permissions.enabled: false` for repositories where release workflows dominate." }] },
  { ruleId: "security.github-actions-pull-request-target", pillar: "security", severity: "warning", confidence: "medium", description: "Flags pull_request_target workflows paired with risky execution or trust context.", remediation: "Use pull_request for untrusted code or isolate checkout, secrets, and write permissions behind trust checks.", falsePositiveShapes: [{ shape: "A safe `pull_request_target` job (label-only, no checkout of PR head) sharing a workflow file with an unrelated job that has a `run:` step or a `secrets.` reference — pullRequestTargetRiskContext scans the whole file and is not scoped to the triggering job.", mitigation: "Split the pull_request_target job into its own workflow file so the risk signals no longer share a file, or set `rules.security.github-actions-pull-request-target.enabled: false`." }, { shape: "A guard line that names the event in order to exclude it, such as `if: github.event_name != 'pull_request_target'`, satisfies hasPullRequestTargetEvent because that predicate is a bare /\\bpull_request_target\\b/ token test on any non-comment line.", mitigation: "Express the guard without naming the event (for example by allowlisting the events you do want), or set `rules.security.github-actions-pull-request-target.enabled: false`." }] },
  { ruleId: "security.github-actions-remote-shell", pillar: "security", severity: "warning", confidence: "medium", description: "Flags workflow run steps that pipe remote downloads to a shell.", remediation: "Vendor the installer, pin an audited action, or verify downloaded content before execution.", falsePositiveShapes: [{ shape: "Documentation or echoed text inside a `run:` block scalar that merely quotes the pattern (`echo \"install with: curl https://example.com/i.sh | sh\"`) is flagged, because runCommands joins the block's raw lines and isRemoteShellCommand does no shell quoting analysis.", mitigation: "Move the sample text into a YAML comment line, which function isCommentOrBlank skips, or set `rules.security.github-actions-remote-shell.enabled: false`." }, { shape: "A pinned official installer from a vendor you already trust (rustup, uv, nvm) is treated identically to an arbitrary URL — the regex has no host allowlist.", mitigation: "Replace the pipe with a pinned setup action or a vendored, checksum-verified installer as the remediation says, or set `rules.security.github-actions-remote-shell.enabled: false`." }] },
  { ruleId: "security.github-actions-secrets-in-pr", pillar: "security", severity: "warning", confidence: "medium", description: "Flags pull request workflows that reference GitHub secrets.", remediation: "Avoid exposing secrets to pull request workflows unless the code path is trusted and tightly gated.", falsePositiveShapes: [{ shape: "A workflow triggered by both `push` and `pull_request` reports the `secrets.` references that belong exclusively to the push-only job, because the pull-request gate is whole-file and the per-line secret scan is not job-scoped.", mitigation: "Split the pull-request job into its own workflow file, or set `rules.security.github-actions-secrets-in-pr.enabled: false`." }, { shape: "`secrets.GITHUB_TOKEN`, the automatically minted per-run token whose scope is already governed by the workflow's `permissions:` block, is reported like a long-lived credential — secretReference matches any `secrets.NAME` and exempts nothing.", mitigation: "Use the `github.token` context expression instead of `secrets.GITHUB_TOKEN` so the line no longer matches, or set `rules.security.github-actions-secrets-in-pr.enabled: false`." }] },
  { ruleId: "security.github-actions-unpinned-action", pillar: "security", severity: "warning", confidence: "medium", description: "Flags third-party GitHub Actions that are not pinned to a full commit SHA.", remediation: "Pin third-party actions to a reviewed 40-character commit SHA and update them deliberately.", falsePositiveShapes: [{ shape: "First-party actions maintained by your own organisation (`myorg/ci-actions@v1`) are classified as third-party, because function thirdPartyActionUse exempts only the two literal owners `actions` and `github` and has no configurable owner allowlist.", mitigation: "Reference the action by local path (`uses: ./.github/actions/…`), which the detector exempts, or set `rules.security.github-actions-unpinned-action.enabled: false`." }] },
  { ruleId: "security.inner-html", pillar: "security", severity: "warning", confidence: "high", description: "Flags innerHTML assignment.", remediation: "Use safe DOM APIs or sanitize trusted HTML centrally." },
  { ruleId: "security.insecure-random", pillar: "security", severity: "warning", confidence: "high", description: "Flags Math.random usage in source.", remediation: "Use crypto-backed randomness for security-sensitive values." },
  { ruleId: "security.javascript-url", pillar: "security", severity: "error", confidence: "high", description: "Flags javascript: URL literals that execute script.", remediation: "Use safe routes or event handlers instead of executable URL strings." },
  { ruleId: "security.new-function", pillar: "security", severity: "error", confidence: "high", description: "Flags Function constructor dynamic code execution.", remediation: "Replace dynamic construction with explicit functions or dispatch." },
  { ruleId: "security.open-redirect-candidate", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external input sent to redirect or navigation sinks.", remediation: "Redirect only to relative paths or destinations from an allowlist.", falsePositiveShapes: [{ shape: "A redirect built from deploy-time operator configuration, e.g. `res.redirect(`${process.env.APP_BASE_URL}/login`)`, because `process.env.*` is one of the SOURCE_TOKENS and is treated as external input even though only the operator sets it.", mitigation: "Read the env value into a module-level constant outside any function and use that constant at the sink — taint is not inherited across function boundaries (`function isFunctionLike` marks scope edges) — or set `rules.security.open-redirect-candidate.enabled: false`." }, { shape: "A redirect target already narrowed by a project validator, e.g. `res.redirect(resolveSafeTarget(req.query.next))`, because only regex-escape helpers are recognised as sanitizers by `function isSafeWrapperExpression`; every other wrapper call keeps the taint.", mitigation: "Branch on the validated key and pass a fixed string literal to the redirect call, or set `rules.security.open-redirect-candidate.enabled: false`." }] },
  { ruleId: "security.path-traversal-candidate", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external input sent to filesystem path sinks.", remediation: "Validate paths against an allowlist and resolve them under a safe root.", falsePositiveShapes: [{ shape: "CLI tooling that intentionally opens an operator-supplied path, e.g. `readFileSync(process.argv[2])` or a path built from `process.env.CONFIG_DIR`, since `process.argv` and `process.env.*` are external-input tokens even though the person running the command owns the path.", mitigation: "Hoist the env/argv read to a module-level constant used inside the function (taint does not cross function boundaries), or set `rules.security.path-traversal-candidate.enabled: false` for CLI-only packages." }, { shape: "A non-filesystem method whose bare name collides with the sink list — the AST matcher is `/(?:^|\\.)(?:…|stat|rm|mkdir|readdir|…)$/` on callee text — so `cache.stat(req.params.id)` or a storage abstraction's `store.rm(...)` is treated as a filesystem sink.", mitigation: "Rename the colliding method away from the fs-API vocabulary, or set `rules.security.path-traversal-candidate.enabled: false`." }] },
  { ruleId: "security.process-exec", pillar: "security", severity: "warning", confidence: "high", description: "Flags child-process execution calls, grading severity from command-source and shell-mode evidence: warning only when a shell-enabled call takes a dynamic command.", remediation: "Review the command source and shell mode; prefer fixed command vectors with shell disabled." },
  { ruleId: "security.proto-access", pillar: "security", severity: "warning", confidence: "medium", description: "Flags direct __proto__ access that can enable prototype pollution.", remediation: "Use Object.getPrototypeOf, Object.create(null), or validated keys.", falsePositiveShapes: [{ shape: "Prototype-pollution defences that must name the key to block it, e.g. `delete payload[\"__proto__\"]` or `if (key === \"__proto__\") continue`, which match the bracket pattern even though they are the mitigation rather than the defect.", mitigation: "Build the object with `Object.create(null)` or key it through a `Map` so the guard is unnecessary, or set `rules.security.proto-access.enabled: false`." }, { shape: "Environment shims and prototype-chain assertions that read `value.__proto__` to inspect, not mutate, an object's prototype.", mitigation: "Switch the read to `Object.getPrototypeOf(value)`, which the pattern does not match." }] },
  { ruleId: "security.remote-install-script", pillar: "security", severity: "error", confidence: "medium", description: "Flags package scripts that pipe remote content to a shell.", remediation: "Vendor, pin, or remove remote shell execution.", falsePositiveShapes: [{ shape: "A developer-only bootstrap script that never runs during install — `function analysePackageScripts` iterates every key in `scripts`, so `\"setup:tools\": \"curl -fsSL https://example.com/install.sh | sh\"` is reported at error severity exactly like a `postinstall` hook.", mitigation: "Vendor or pin the installer as a registry dependency, or set `rules.security.remote-install-script.enabled: false` if the bootstrap is a reviewed, out-of-band developer step." }] },
  { ruleId: "security.risky-lifecycle-script", pillar: "security", severity: "warning", confidence: "medium", description: "Flags install-time and side-effectful publish lifecycle scripts while allowing validation-only publish gates.", remediation: "Review whether lifecycle execution is required; keep install/publish side effects behind explicit commands when possible.", falsePositiveShapes: [{ shape: "The standard `prepare` idiom — building on git install or running `husky install` — which `function isValidationOnlyLifecycleCommand` can never exempt because it returns false for every script name other than prepublish/prepublishOnly.", mitigation: "Move the work into an explicit named script invoked by CI, or set `rules.security.risky-lifecycle-script.enabled: false`." }, { shape: "A genuinely validation-only `prepublishOnly` that chains commands, e.g. `npm run lint && npm test`, which is rejected by the `[;&|`$<>]` metacharacter guard before the allowlist is consulted.", mitigation: "Collapse the gate into a single allowlisted validation command, or set `rules.security.risky-lifecycle-script.enabled: false`." }] },
  { ruleId: "security.sql-concatenation", pillar: "security", severity: "warning", confidence: "high", description: "Flags SQL text composed with runtime interpolation or concatenation in query, execute, raw, or prepare calls.", remediation: "Use parameterized values, and keep dynamic identifiers constrained to trusted constants or explicit review." },
  { ruleId: "security.ssrf-candidate", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external input sent to network request sinks.", remediation: "Validate destinations against an allowlist and block internal hosts.", falsePositiveShapes: [{ shape: "Validation on an earlier line or inside a helper can be outside the same-line candidate evidence.", mitigation: "Keep the destination allow-list visible at the sink or review the warning with its surrounding validation." }] },
  { ruleId: "security.string-timer", pillar: "security", severity: "warning", confidence: "high", description: "Flags string callbacks passed to timers.", remediation: "Pass a function callback instead of source text." },
  { ruleId: "security.throw-non-error", pillar: "security", severity: "warning", confidence: "medium", description: "Flags thrown non-Error values.", remediation: "Throw an Error subclass with a clear message.", falsePositiveShapes: [{ shape: "Deliberate structured control-flow payloads that a framework contract expects, e.g. `throw { status: 404, body }` in an HTTP handler, which match the object-literal branch even though the shape is intentional.", mitigation: "Throw an Error subclass that carries the payload as properties (`throw new HttpError(404, body)` is exempt because the expression starts with an identifier), or set `rules.security.throw-non-error.enabled: false`." }] },
  { ruleId: "security.unsafe-deserialization", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external input reaching unsafe deserialization or dynamic code-loading sinks.", remediation: "Use schema-bound parsers or validate and decode data without executing code.", falsePositiveShapes: [{ shape: "A CLI loading its own YAML config with `yaml.load(readFileSync(process.argv[2]))`, where the operator supplies the file but `function isUnsafeYamlLoad` still treats the load as unsafe because no schema is pinned.", mitigation: "Pass `{ schema: JSON_SCHEMA }` (or FAILSAFE_SCHEMA/CORE_SCHEMA) as the second argument — `function hasSafeYamlSchema` then clears the finding." }, { shape: "A project's own codec method named `unserialize` that only decodes data structures — the matcher is `/(?:^|\\.)unserialize$/` on callee text and does not check what the method does.", mitigation: "Rename the method (e.g. to `decode`), or set `rules.security.unsafe-deserialization.enabled: false`." }] },
  { ruleId: "security.url-dependency", pillar: "security", severity: "warning", confidence: "medium", description: "Flags dependencies installed from URL, git, or local file specs.", remediation: "Prefer registry versions that can be locked and audited.", falsePositiveShapes: [{ shape: "Intentional monorepo-local links such as `\"@acme/shared\": \"file:../shared\"` in devDependencies, which are unpublishable by design yet match the `file:` branch.", mitigation: "Use the package manager's workspace protocol if the toolchain supports it, or set `rules.security.url-dependency.enabled: false` for the internal package." }, { shape: "A git spec already pinned to an immutable commit, e.g. `\"github:org/repo#a1b2c3d\"`, which the regex accepts through its optional `(?:#.+)?` tail and reports the same as an unpinned branch reference.", mitigation: "Publish the fork to a registry so the version can be locked and audited, or set `rules.security.url-dependency.enabled: false`." }] },
  { ruleId: "security.weak-crypto", pillar: "security", severity: "warning", confidence: "high", description: "Flags weak crypto primitives such as md5, sha1, or createCipher.", remediation: "Use modern algorithms and authenticated encryption." },
  { ruleId: "security.xxe-candidate", pillar: "security", severity: "warning", confidence: "medium", description: "Flags external XML reaching parsers configured to expand entities.", remediation: "Disable external entity expansion and use hardened XML parser options.", falsePositiveShapes: [{ shape: "An explicitly hardened xmldom parser: `function hasUnsafeXmlParserOption` matches the bare key `\\bresolveEntity\\s*:` with no constraint on its value, so `resolveEntity: () => null` or `resolveEntity: false` — the fix — is read as entity-expansion evidence.", mitigation: "Drop the explicit `resolveEntity` key and rely on the parser's non-expanding default, or set `rules.security.xxe-candidate.enabled: false`." }, { shape: "A pipeline that deliberately expands entities over first-party XML the project itself ships, which still matches because `processEntities: true`/`noent: true` is the only evidence the detector needs once an external-input token is in scope.", mitigation: "Pre-expand the trusted document at build time and parse with entity expansion off, or set `rules.security.xxe-candidate.enabled: false`." }] },
  { ruleId: "sensitive-data.api-key-pattern", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags vendor API key patterns including GitHub, GitLab, npm, Google API, Slack, Discord, and Stripe/OpenAI-style keys.", remediation: "Remove the secret and load it from a secure runtime source." },
  { ruleId: "sensitive-data.aws-access-key", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags AWS access key looking values.", remediation: "Remove the key and rotate it immediately." },
  { ruleId: "sensitive-data.database-url-password", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags database and HTTP(S) URLs that include passwords or embedded credentials.", remediation: "Move credentials into a secret store or runtime environment." },
  { ruleId: "sensitive-data.gcp-service-account-key", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags GCP service-account key files (type service_account alongside a private key).", remediation: "Remove the service-account key from source and rotate it; load credentials from a secure runtime source." },
  { ruleId: "sensitive-data.hardcoded-env-value", pillar: "sensitive-data", severity: "error", confidence: "medium", description: "Flags environment-style secret values committed in text.", remediation: "Load secret-like values from secure runtime configuration. Or raise rules.sensitive-data.hardcoded-env-value.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 16, falsePositiveShapes: [{ shape: "A non-secret configuration line whose key merely contains a secret word: a resource path assigned to an uppercase SECRET-prefixed key, or an OAuth endpoint URL assigned to a TOKEN-prefixed key. SECRET_ASSIGNMENT_PATTERN accepts any uppercase key containing TOKEN, SECRET, PASSWORD, or DSN, and the value need only reach the threshold length with one letter and one digit.", mitigation: "Raise `rules.sensitive-data.hardcoded-env-value.threshold` in .gruff-ts.yaml if the length bound is wrong for the project, or add a `sensitiveExclusions` entry naming the rule, path, and reason for that file." }, { shape: "Template and documentation values in non-script files such as .env.example, YAML, .pypirc, and Markdown, where a sample placeholder is assigned to an API-key variable. The quoted-value requirement applies only to script extensions, and `isPlaceholderSecretValue` exempts only the bare words x-api-key, token, secret, password, example, sample, and placeholder.", mitigation: "Shorten the sample below `rules.sensitive-data.hardcoded-env-value.threshold`, or replace it with one of the recognised placeholder words such as `example`; otherwise scope a `sensitiveExclusions` entry to the template path." }] },
  { ruleId: "sensitive-data.high-entropy-string", pillar: "sensitive-data", severity: "error", confidence: "medium", description: "Flags high-entropy string literals that may be secrets.", remediation: "Remove the value and load it from a secure runtime source. Or raise rules.sensitive-data.high-entropy-string.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 32, falsePositiveShapes: [{ shape: "Deliberately public opaque credentials such as a Stripe publishable key or an OAuth client id: the long mixed-case-plus-digit segment trips `isTokenLikeSegmentedSecret`, which withdraws the readable-identifier exemption, so the literal is reported as a probable secret.", mitigation: "Add a `sensitiveExclusions` entry in .gruff-ts.yaml naming rule `sensitive-data.high-entropy-string` with the file path and a reason, or set `rules.sensitive-data.high-entropy-string.enabled: false` if the project has no entropy secrets to find." }, { shape: "Base64 test vectors, inline certificate bodies, and encoded fixture blobs held in string literals, since the exclusion chain exempts only all-hex digests, `sha1/256/384/512-` SRI hashes, known repo-path shapes, character alphabets, and word-segment identifiers, so mixed-case base64 payloads clear every gate.", mitigation: "Raise `rules.sensitive-data.high-entropy-string.threshold` above the benign literal's length, or scope a `sensitiveExclusions` entry to the fixture path so the suppression stays auditable." }] },
  { ruleId: "sensitive-data.jwt-token", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags JWT-looking token literals.", remediation: "Remove the token and rotate the credential if real." },
  { ruleId: "sensitive-data.phi-pattern", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags PHI identifiers such as Medicare (MBI) and medical record numbers.", remediation: "Remove protected health information from source and fixtures." },
  { ruleId: "sensitive-data.pii-pattern", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags PII-like identifier patterns including SSN-shaped values and Luhn-valid payment cards.", remediation: "Remove personal data from source and fixtures." },
  { ruleId: "sensitive-data.private-key", pillar: "sensitive-data", severity: "error", confidence: "high", description: "Flags private key block markers.", remediation: "Remove the key material and rotate affected credentials." },
  { ruleId: "size.file-length", pillar: "size", severity: "error", confidence: "high", description: "Flags files whose substantive nonblank, non-comment line count exceeds the configured threshold.", remediation: "Split unrelated responsibilities into smaller files. Or raise rules.size.file-length.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 1000 },
  { ruleId: "size.function-length", pillar: "size", severity: "warning", confidence: "high", description: "Flags functions longer than the configured threshold.", remediation: "Extract named helpers or split workflows. Or raise rules.size.function-length.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 200 },
  { ruleId: "size.parameter-count", pillar: "size", severity: "warning", confidence: "high", description: "Flags functions with too many parameters.", remediation: "Group related options or reduce the function's responsibility. Or raise rules.size.parameter-count.threshold in .gruff-ts.yaml if the bound is wrong for this project.", threshold: 7 },
  { ruleId: "test-quality.conditional-logic", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests with conditional logic.", remediation: "Split branch-specific expectations into separate tests." },
  { ruleId: "test-quality.exception-type-only", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests that only assert exception type.", remediation: "Assert message, code, or observable behavior as well." },
  { ruleId: "test-quality.global-state-mutation", pillar: "test-quality", severity: "warning", confidence: "high", description: "Flags tests mutating process or global runtime state.", remediation: "Isolate state changes and restore them around the test." },
  { ruleId: "test-quality.loop-in-test", pillar: "test-quality", severity: "advisory", confidence: "medium", description: "Flags test-body loops whose assertions do not identify the failing iteration.", remediation: "Add a per-case message to looped assertions, or use a fixture table or separate named cases.", falsePositiveShapes: [{ shape: "A parametrized loop whose assertion does carry a per-case message, but written across multiple lines — `isLabeledCaseLoop` splits the loop body on `[;\\n]` before testing each statement for an assertion, so a multi-line assertion call loses its label and the loop is reported even though the failing row is identifiable.", mitigation: "Keep the looped assertion call and its per-case message on one statement line so `isLabeledCaseLoop` can see the loop-bound name, or set `rules.test-quality.loop-in-test.enabled` to false." }, { shape: "A loop that only builds fixture data but calls a helper whose name ends in `Check` (or touches `.resolves`/`.rejects`), which `hasAssertion` in src/blocks.ts treats as an assertion — the loop is reported although no expectation runs per iteration.", mitigation: "Rename the helper away from the `Check` suffix, hoist the data-building loop out of the test body, or set `rules.test-quality.loop-in-test.enabled` to false." }] },
  { ruleId: "test-quality.magic-number-assertion", pillar: "test-quality", severity: "advisory", confidence: "medium", description: "Flags assertions against unexplained numeric literals.", remediation: "Name expected values or assert domain-specific outcomes.", falsePositiveShapes: [{ shape: "An assertion against a documented domain constant that is neither a small cardinal nor a length matcher — e.g. `assert.equal(timeoutMs, 30000)` — where the literal itself is the contract; only the words constant/threshold/limit/budget/default/contract in the TEST NAME exempt it (`isConstantContractTestName`).", mitigation: "Name the expected value as a shared constant and assert against that, or include one of the exempting words (e.g. 'default', 'threshold', 'contract') in the test title." }, { shape: "An HTTP status assertion whose actual expression does not spell `status` or `statusCode` — `isHttpStatusAssertion` requires that word in the expression, so `assert.equal(response.code, 404)` is reported while `response.status` is not.", mitigation: "Assert through the `status`/`statusCode` property so the built-in exemption applies, or set `rules.test-quality.magic-number-assertion.enabled` to false." }] },
  { ruleId: "test-quality.mock-only-test", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests that only verify mock interaction.", remediation: "Assert observable behavior in addition to collaboration." },
  { ruleId: "test-quality.no-assertions", pillar: "test-quality", severity: "warning", confidence: "high", description: "Flags tests without apparent assertions.", remediation: "Add assertions for observable behavior." },
  { ruleId: "test-quality.no-throw-only-test", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests that only assert code does not throw.", remediation: "Assert the observable result or state change." },
  { ruleId: "test-quality.only-skip", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags focused or skipped test markers.", remediation: "Remove .only and either enable or delete skipped tests." },
  { ruleId: "test-quality.sleep-in-test", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags sleeps in tests.", remediation: "Synchronize on behavior instead of wall-clock time." },
  { ruleId: "test-quality.snapshot-only-test", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests that rely only on snapshots.", remediation: "Add targeted assertions for important behavior." },
  { ruleId: "test-quality.static-analysis-redundant-test", pillar: "test-quality", severity: "advisory", confidence: "high", description: "Flags tests that primarily assert code shape rather than behavior, with review guidance for importability sentinels.", remediation: "Remove redundant assertions, replace them with behavioral evidence, or document why runtime module-load coverage matters." },
  { ruleId: "test-quality.trivial-assertion", pillar: "test-quality", severity: "warning", confidence: "high", description: "Flags tautological assertions.", remediation: "Assert a real result from the system under test." },
  { ruleId: "test-quality.unused-mock", pillar: "test-quality", severity: "advisory", confidence: "medium", description: "Flags mocks created but not used.", remediation: "Remove unused mocks or wire them into the behavior under test.", falsePositiveShapes: [{ shape: "A `sinon.stub(target, \"method\")` whose whole purpose is the install side effect — it patches the method on the target object, so the test exercises the target and asserts observable output without ever naming the returned stub again, and the single-occurrence count reports it as unused.", mitigation: "Assert through the stub (e.g. `sinon.assert.calledWith(stubName, ...)`) so the binding is referenced, or set `rules.test-quality.unused-mock.enabled` to false for suites that install stubs this way." }] },
  { ruleId: "waste.any-type", pillar: "maintainability", severity: "warning", confidence: "high", description: "Flags any type usage.", remediation: "Use unknown with validation or a precise type." },
  { ruleId: "waste.broad-runtime-version", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags broad runtime dependency version ranges.", remediation: "Use bounded semver ranges and lockfiles.", falsePositiveShapes: [{ shape: "A deliberately bounded multi-range spec such as `\"^18.0.0 || ^20.0.0\"`, flagged only because `isBroadRuntimeVersion` treats the presence of `||` as broad even though every alternative in the union is upper-bounded.", mitigation: "Collapse the union to one bounded range if you can support only one major, or set `rules.waste.broad-runtime-version.enabled` to false when dual-major support is a deliberate policy." }, { shape: "A plugin or adapter package that must float with its host, declaring an intentionally open `>=` spec (e.g. `\"typescript\": \">=5\"`), which matches the `/^>=\\s*\\d/` branch because it has no `<` upper bound.", mitigation: "Add an upper bound (`\">=5 <7\"`) so the range is auditable, or disable via `rules.waste.broad-runtime-version.enabled`." }] },
  { ruleId: "waste.commented-out-code", pillar: "maintainability", severity: "advisory", confidence: "high", description: "Flags comments that appear to contain disabled code.", remediation: "Delete dead code or restore it behind a real feature path." },
  { ruleId: "waste.console-log", pillar: "maintainability", severity: "advisory", confidence: "high", description: "Flags console log/debug calls in source.", remediation: "Remove debug logging or route through structured logging." },
  { ruleId: "waste.empty-function", pillar: "maintainability", severity: "advisory", confidence: "high", description: "Flags functions with no executable body.", remediation: "Delete the function or add the missing implementation." },
  { ruleId: "waste.exported-any", pillar: "maintainability", severity: "warning", confidence: "medium", description: "Flags exported APIs exposing any.", remediation: "Use a named interface, unknown with validation, or precise generics.", falsePositiveShapes: [{ shape: "A one-line exported arrow function whose `any` lives in the body rather than the signature — e.g. `export const trim = (v: string): string => (v as any).trim();` — flags as a public-contract `any` because the check is line-scoped and matches `\\bany\\b` anywhere on the export line.", mitigation: "Move the body onto its own line so the internal cast leaves the declaration line, or set `rules.waste.exported-any.enabled` to false." }, { shape: "A deliberately variadic exported utility type or signature such as `export type AnyFn = (...args: any[]) => unknown;`, where `any[]` is the only way to accept arbitrary argument tuples.", mitigation: "Replace `any[]` with `unknown[]` (call sites narrow at use), or disable via `rules.waste.exported-any.enabled`." }] },
  { ruleId: "waste.redundant-boolean-cast", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags redundant boolean casts in condition expressions.", remediation: "Use the condition value directly or name the boolean conversion.", falsePositiveShapes: [{ shape: "A predicate whose leading coercion is compared or combined rather than used as the condition itself — e.g. `if (Boolean(a) !== Boolean(b))` or `if (!!left === !!right)` — matches because the regex only inspects the opening tokens after `if (`, yet the coercion is load-bearing for the comparison.", mitigation: "Hoist each coercion into a named boolean local (`const hasA = Boolean(a);`) so the predicate no longer opens with the cast, or set `rules.waste.redundant-boolean-cast.enabled` to false." }] },
  { ruleId: "waste.redundant-variable", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags variables returned immediately after assignment.", remediation: "Return the expression directly.", falsePositiveShapes: [{ shape: "An awaited temporary inside a `try` block — `const value = await fetchThing(); return value;` — where inlining to `return fetchThing();` drops the await and moves rejection handling outside the `try`/`catch`, changing behaviour.", mitigation: "Inline as `return await fetchThing();` rather than `return fetchThing();`, or set `rules.waste.redundant-variable.enabled` to false for code that leans on await-in-try semantics." }] },
  { ruleId: "waste.swallowed-catch", pillar: "maintainability", severity: "warning", confidence: "medium", description: "Flags empty catch blocks.", remediation: "Handle, report, rethrow, or document intentional ignore paths.", falsePositiveShapes: [{ shape: "An intentionally empty catch whose comment explains the reason in wording outside the accepted rationale vocabulary — the allowlist keys on tokens such as `ignore`, `ignored`, `cleanup`, `teardown`, `noop`, and `no-op`, and deliberately excludes `silent` — so `catch { // optional feature, absence is expected }` still flags.", mitigation: "Reword the comment to include an accepted rationale token (e.g. `// intentional no-op: optional feature`), or set `rules.waste.swallowed-catch.enabled` to false." }] },
  { ruleId: "waste.useless-catch", pillar: "maintainability", severity: "advisory", confidence: "high", description: "Flags catch blocks that only rethrow the caught value.", remediation: "Remove the catch block or add meaningful handling." },
  { ruleId: "waste.useless-return", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags terminal bare return statements in void functions.", remediation: "Remove the final return statement.", falsePositiveShapes: [{ shape: "A genuine early-exit guard that happens to be the textually last statement — the upward walk in `terminalBareReturnLines` skips over `}` lines, so a `return;` inside a trailing `if (…) { … }` block is attributed to the whole function even though it is conditional and load-bearing.", mitigation: "Write the guard on one line (`if (done) return;`) so the walk does not land on a bare `return;`, or set `rules.waste.useless-return.enabled` to false." }] },
  { ruleId: "waste.unreachable-code", pillar: "maintainability", severity: "warning", confidence: "high", description: "Flags statements after terminating statements.", remediation: "Delete unreachable code or restructure the control flow." },
  { ruleId: "waste.unused-import", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags named imports with no apparent usage.", remediation: "Remove unused imports.", falsePositiveShapes: [{ shape: "An import used exactly once, inside a template-literal interpolation that itself contains braces — e.g. `` `${format({ level: Level.Warn })}` `` — because the rescue regex `\\$\\{[^}]*\\bNAME\\b[^}]*\\}` cannot cross the inner `}`, so the masked count stays at 1 and the binding looks unused.", mitigation: "Bind the value to a local before the template (`const level = Level.Warn;`) so the reference appears in plain code, or set `rules.waste.unused-import.enabled` to false." }] },
  { ruleId: "waste.unused-parameter", pillar: "maintainability", severity: "advisory", confidence: "medium", description: "Flags parameters with no apparent usage.", remediation: "Remove the parameter or prefix it with _ if intentional.", falsePositiveShapes: [{ shape: "A parameter referenced only inside a template-literal interpolation that contains braces — e.g. `` `${render({ user })}` `` — because the rescue regex `\\$\\{[^}]*\\bNAME\\b[^}]*\\}` stops at the inner `}` and the mask hides the interpolation from the plain body search.", mitigation: "Reference the parameter in plain code before the template, or prefix it with `_` if it really is unused; `rules.waste.unused-parameter.enabled` disables the rule outright." }] },
];

/**
 * Return the deterministic rule catalogue used by list-rules.
 *
 * @returns Sorted rule descriptor metadata.
 */
export function ruleDescriptors(): RuleDescriptor[] {
  return [...RULE_DESCRIPTORS].sort((left, right) => left.ruleId.localeCompare(right.ruleId));
}
